]$topics$::jsonb) as p(field text,grade text,subject text,chapter text,position integer,title text,start integer,"end" integer,konkur boolean)),
tracks(track) as (values ('konkur'),('final_exam'))
insert into private.planner_topic_bank(id,edition,study_field,grade,preparation_track,subject,chapter,title,page_start,page_end,position)
select md5('nova:planner:1405:v235:'||p.field||':'||p.grade||':'||r.track||':'||p.subject||':'||p.chapter||':'||p.position)::uuid,'1405',p.field,p.grade,r.track,p.subject,p.chapter,p.title,p.start,p."end",p.position from topics p cross join tracks r cross join installed where p.konkur or r.track='final_exam' on conflict(id) do nothing;

-- Pattern B: page-fill of the eight pristine مطالعات اجتماعی ۹ whole-lesson rows from
-- migration 151 (v1 ids, revision 1, NULL pages). Verified against the 1405 PDF:
-- درس ۷ pp.42–46, درس ۸ pp.47–52, درس ۱۳ pp.82–87, درس ۱۴ pp.88–94,
-- درس ۱۵ pp.96–104, درس ۱۶ pp.105–116, درس ۲۳ pp.158–163, درس ۲۴ pp.164–170.
update private.planner_topic_bank t set page_start=p.start,page_end=p."end",revision=t.revision+1,updated_at=now()
from (values
  ('فصل ۴: ساکنان سیاره زمین',1,'درس ۷: جمعیت جهان',42,46),
  ('فصل ۴: ساکنان سیاره زمین',2,'درس ۸: بی‌عدالتی و نابرابری در جهان',47,52),
  ('فصل ۷: ایران در عصر مشروطه',1,'درس ۱۳: نهضت مشروطه',82,87),
  ('فصل ۷: ایران در عصر مشروطه',2,'درس ۱۴: ایران در دوران حکومت پهلوی',88,94),
  ('فصل ۸: سقوط حکومت شاهنشاهی و شکل‌گیری نظام جمهوری اسلامی',1,'درس ۱۵: انقلاب اسلامی ایران',96,104),
  ('فصل ۸: سقوط حکومت شاهنشاهی و شکل‌گیری نظام جمهوری اسلامی',2,'درس ۱۶: ایران در دوران پس از پیروزی انقلاب اسلامی',105,116),
  ('فصل ۱۲: بهره‌وری',1,'درس ۲۳: بهره‌وری چیست؟',158,163),
  ('فصل ۱۲: بهره‌وری',2,'درس ۲۴: اقتصاد و بهره‌وری',164,170)
) p(chapter,position,title,start,"end")
where t.id=md5('nova:planner:1405:v1:all:9:final_exam:مطالعات اجتماعی:'||p.chapter||':'||p.position)::uuid
 and t.edition='1405' and t.study_field='all' and t.grade='9'
 and t.preparation_track='final_exam' and t.subject='مطالعات اجتماعی' and t.chapter=p.chapter
 and t.title=p.title and t.position=p.position
 and t.page_start is null and t.page_end is null and t.revision=1;
